from pathlib import Path
import base64
root=Path(__file__).resolve().parent
img=base64.b64encode((root/'abe-simpson.jpg').read_bytes()).decode()
html=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>What is JEV? A decision model</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#191d21;color:#202721;font-family:Arial,Helvetica,sans-serif}.slide{display:none;width:100vw;min-height:100vh;padding:7vh 8vw 12vh;background:#f3f1e8}.slide.active{display:flex;flex-direction:column;justify-content:center}.eyebrow{font-size:16px;letter-spacing:.14em;text-transform:uppercase;color:#526653;margin:0 0 30px}h1{font-size:clamp(62px,8vw,120px);line-height:.95;letter-spacing:-.065em;margin:0 0 24px}h2{font-size:clamp(42px,5.6vw,82px);letter-spacing:-.05em;line-height:1.02;margin:0 0 36px}.subtitle{font-size:clamp(30px,3.7vw,54px);color:#52704c;margin:0 0 38px;letter-spacing:-.035em}.intro{font-size:clamp(22px,2.4vw,34px);max-width:950px;line-height:1.35;margin:0 0 44px}.flow{display:flex;align-items:center;gap:25px;border-top:1px solid #bbc3b4;padding-top:26px;font-size:clamp(18px,2vw,28px)}.flow span:nth-child(even){color:#708166}.meme{background:#dceb59}.meme.active{flex-direction:row;gap:6vw;align-items:center}.meme h2{font-size:clamp(38px,5.4vw,78px);max-width:660px;margin:0}.meme img{width:43%;max-height:65vh;object-fit:contain;box-shadow:8px 10px 0 #202721}.answer{font-size:clamp(25px,3vw,44px);max-width:1000px;line-height:1.16;margin:0 0 40px}.answer strong{color:#52704c}.points{display:grid;grid-template-columns:repeat(3,1fr);gap:3vw;border-top:1px solid #bbc3b4;padding-top:26px}.points h3{font-size:clamp(20px,2vw,29px);margin:0 0 13px;letter-spacing:-.03em}.points p{font-size:clamp(17px,1.65vw,24px);line-height:1.4;margin:0}.caveat{font-size:16px;margin:30px 0 0;color:#526653}.controls{position:fixed;bottom:20px;left:8vw;right:8vw;display:flex;align-items:center;gap:10px;color:#202721;font-size:13px}.controls button{border:1px solid #a8b09e;border-radius:30px;padding:9px 15px;color:inherit;background:#f3f1e8;cursor:pointer;font:inherit}.controls button:disabled{opacity:.35;cursor:default}.controls .spacer{flex:1}.controls button:focus-visible,a:focus-visible{outline:3px solid #52704c;outline-offset:3px}dialog{max-width:700px;max-height:75vh;border:0;padding:35px;background:#f3f1e8;color:#202721;line-height:1.6}dialog::backdrop{background:#0009}dialog h2{font-size:28px;margin-bottom:20px}a{color:#365b31}.notes{display:none} @media(max-width:700px){.slide{padding:8vh 7vw 110px}.meme.active{flex-direction:column;justify-content:center;gap:28px}.meme img{width:70%;max-height:38vh}.points{grid-template-columns:1fr;gap:20px}h2{margin-bottom:25px}.answer{margin-bottom:26px}.intro{margin-bottom:25px}.flow{gap:10px;flex-wrap:wrap}.controls{left:7vw;right:7vw;bottom:15px}.hint{display:none}.caveat{font-size:14px}}@media print{@page{size:landscape;margin:0}body{background:white}.slide,.slide.active{display:flex;width:100%;height:100vh;break-after:page}.meme{flex-direction:row}.controls,dialog{display:none!important}}
</style></head><body>
<main aria-label="What is JEV? A decision model">
<section class="slide active" aria-label="Slide 1 of 3"><p class="eyebrow">TypeSafe AI</p><h1>What is JEV?</h1><p class="subtitle">A decision model</p><p class="intro">A general-purpose classifier for focused decisions.<br>Give it context and a question. Get a choice, a score, or a probability.</p><div class="flow"><span>Context</span><span>+</span><span>Typed question</span><span>→</span><span>Structured decision</span></div><div class="notes">JEV is TypeSafe AI’s first System One model, introduced September 15, 2026. “General-purpose classifier” is a useful shorthand: it also supports rubric-based scoring and true/false probabilities. Sources: https://typesafe.ai/blog/introducing-system-one-models-and-jev and https://docs.typesafe.ai/introduction</div></section>
<section class="slide meme" aria-label="Slide 2 of 3" hidden><h2>“Autoregression<br>has been around<br>for decades!”</h2><img src="data:image/jpeg;base64,IMAGE" alt="Abe Simpson shaking his fist at a cloud, beneath the newspaper headline Old Man Yells at Cloud"><div class="notes">The skeptical interlude. Autoregression is longstanding; classification is also longstanding. These are distinct concepts. JEV’s novelty claim concerns its decision-focused model and interface, not inventing classification or autoregression. Image: The Simpsons, via https://laagenda.buenosaires.gob.ar/contenido/22021-gritarle-a-una-nube</div></section>
<section class="slide" aria-label="Slide 3 of 3" hidden><h2>Yes, that’s true</h2><p class="answer">With JEV, you can define a new task<br><strong>without collecting a training dataset.</strong></p><div class="points"><div><h3>Describe the decision</h3><p>Provide context, a question, and the labels or rubric you care about.</p></div><div><h3>Use a pretrained model</h3><p>Start without fitting a separate classifier for each task.</p></div><div><h3>Get probabilities directly</h3><p>Typed outputs in parallel, rather than token-by-token text generation.</p></div></div><p class="caveat">No task-specific training required to start. Evaluation on your own data still matters.</p><div class="notes">No training dataset means no task-specific dataset needed to configure the first call; it does not mean the underlying model was never trained. TypeSafe’s quickstart defines tasks using state and natural-language questions. Zero-shot setup is not unique to JEV. The distinction here combines that setup with a model built for structured probabilistic outputs. Type-safe does not mean always correct. Sources: https://docs.typesafe.ai/introduction/quickstart and https://typesafe.ai/blog/introducing-system-one-models-and-jev</div></section>
</main><nav class="controls" aria-label="Presentation controls"><span id="counter" aria-live="polite">01 / 03</span><span class="spacer"></span><span class="hint">← → to navigate</span><button id="notes">Notes & sources</button><button id="full" aria-label="Toggle fullscreen">Fullscreen</button><button id="prev" aria-label="Previous slide">←</button><button id="next" aria-label="Next slide">→</button></nav><dialog id="dialog"><h2>Presenter notes & sources</h2><p id="noteText"></p><form method="dialog"><button>Close</button></form></dialog>
<script>
const slides=[...document.querySelectorAll('.slide')];let index=0;const counter=document.querySelector('#counter'),prev=document.querySelector('#prev'),next=document.querySelector('#next'),dialog=document.querySelector('#dialog');function show(n){index=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>{s.classList.toggle('active',i===index);s.hidden=i!==index});counter.textContent=`0${index+1} / 03`;prev.disabled=index===0;next.disabled=index===slides.length-1;history.replaceState(null,'',`#${index+1}`)}prev.onclick=()=>show(index-1);next.onclick=()=>show(index+1);document.querySelector('#notes').onclick=()=>{const text=slides[index].querySelector('.notes').textContent;const p=document.querySelector('#noteText');p.textContent='';text.split(/(https:\/\/[^\s]+)/g).forEach(part=>{if(part.startsWith('https://')){const a=document.createElement('a');a.href=part;a.textContent=part;a.target='_blank';a.rel='noopener';p.append(a)}else p.append(document.createTextNode(part))});dialog.showModal()};document.querySelector('#full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{}};document.addEventListener('keydown',e=>{if(dialog.open||e.target.closest('button,a'))return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(index+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(index-1)}if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1)});show((parseInt(location.hash.slice(1))||1)-1);
</script></body></html>'''
(root/'what-is-jev.html').write_text(html.replace('IMAGE',img))
